101	    // Rooftop Storm's alternative cost is handled via the alternative_cost field
102	    // on CastSpell actions (see rooftop_storm_applies() and action generation).
103	    // It is NOT a cost reduction — it's an alternative cost chosen at cast time.
104	
105	    if total_reduction == 0 {
106	        return base_cost.clone();
107	    }
108	
109	    // Apply reduction to generic mana first, keeping colored requirements.
110	    let mut remaining_reduction = total_reduction;
111	    let mut new_symbols = Vec::new();
112	    for sym in &base_cost.symbols {
113	        match sym {
114	            ManaSymbol::Generic(n) => {
115	                if remaining_reduction >= *n {
116	                    remaining_reduction -= *n;
117	                    // Reduced to zero, omit this symbol.
118	                } else {
119	                    new_symbols.push(ManaSymbol::Generic(*n - remaining_reduction));
120	                    remaining_reduction = 0;
121	                }
122	            }
123	            other => new_symbols.push(other.clone()),
124	        }
125	    }
126	    ManaCost::new(new_symbols)
127	}
